%[text] # Second-Order Time Response
%[text] Demonstration of how to visualize the response of a canonical (underdamped) second order model.
%[text] ## Canoncial model
%[text] ![](text:image:108a)
%[text] The real part of the pole pair: $\\zeta \\, \\omega\_n$
zwn = 0.5;
%[text] The imaginary part of the pole pair: $\\omega\_d$
wd = 2*pi;    % rad/s
%[text] ## Create the transfer function
num = zwn^2 + wd^2;
den = conv([1 zwn],[1 zwn]) + [0 0 wd^2];
G = tf( zwn^2 + wd^2, den)
%[text] ## Plot the unit step response
figure(1)
clf()
step(G)
%[text] Note that the "DC Gain" is unity.
%%
%[text] ## Plot the unit impulse response
figure(2)
clf()
impulse(G)
%%
%[text] Overlay the analytical solution for the impulse response
hold on
tt = linspace(0,10,1000);
cc = (zwn^2+wd^2)/wd*exp(-zwn*tt).*sin(wd*tt);
plot(tt,cc,'r--')
%[text] 

